package com.vaultorandroid
import android.content.*
import android.content.pm.PackageManager
import android.net.Uri
import android.provider.Settings
import android.util.AtomicFile
import androidx.core.content.FileProvider
import com.android.apksig.ApkVerifier
import org.json.*
import java.io.*
import java.net.URL
import java.security.MessageDigest
import java.util.concurrent.Executors
import javax.net.ssl.HttpsURLConnection

/** Publisher-only updates. Host credentials, workspace APIs and imported archives never supply APKs. */
class VaultorUpdates(private val ctx:Context,private val changed:()->Unit={},private val metadataFetcher:((String)->String)?=null) {
 companion object {const val MAX=256L*1048576;const val REPO="VaibhavPandit-09/vaultor-kb";private val worker=Executors.newSingleThreadExecutor();private val busy=java.util.concurrent.atomic.AtomicBoolean(false);@Volatile private var cancel=false;private val lock=Any();val DOWNLOAD_HOSTS=setOf("api.github.com","github.com","release-assets.githubusercontent.com","objects.githubusercontent.com")}
 private val root=File(ctx.noBackupFilesDir,"updates-v1").apply {check(mkdirs()||isDirectory)};private val journal=AtomicFile(File(root,"state.json"));private val trust=JSONObject(ctx.assets.open("release-trust.json").bufferedReader().use {it.readText()});var activityProvider:(()->android.app.Activity?)?=null
 private fun installed()=ctx.packageManager.getPackageInfo(ctx.packageName,PackageManager.PackageInfoFlags.of(0))
 private fun read():JSONObject=synchronized(lock){if(!journal.baseFile.exists())JSONObject().put("phase","idle")else JSONObject(String(journal.readFully(),Charsets.UTF_8))}
 private fun save(row:JSONObject)=synchronized(lock){val out=journal.startWrite();try{out.write(row.toString().toByteArray());journal.finishWrite(out)}catch(e:Exception){journal.failWrite(out);throw e};changed()}
 fun snapshot():JSONObject {val row=read();val candidate=row.optJSONObject("candidate");if(candidate!=null&&candidate.optLong("versionCode")<=installed().longVersionCode){row.remove("candidate");row.remove("available");row.put("phase","installed").put("detail","Installed version confirmed by Android. Protected app data remains in place.");save(row);File(root,"candidate.apk").delete();};row.put("currentVersion",installed().versionName).put("currentCode",installed().longVersionCode).put("busy",busy.get()).put("canInstall",ctx.packageManager.canRequestPackageInstalls());if(!busy.get()&&row.optString("phase") in listOf("checking","downloading","verifying"))row.put("phase","interrupted").put("detail","Interrupted update retained. Retry check or choose the APK again; app data is unchanged.");return row}
 private fun action(task:()->Unit){check(busy.compareAndSet(false,true)){"An update action is running"};cancel=false;worker.execute {try{task()}catch(e:Exception){val row=read();row.put("phase",if(cancel)"interrupted" else "error").put("detail",(e.message?:"Update could not complete; existing app and data are unchanged").take(240));save(row)}finally{busy.set(false);changed()}}}
 private fun phase(phase:String,detail:String){val row=read();row.put("phase",phase).put("detail",detail);save(row)}
 private fun connect(raw:String):HttpsURLConnection {var url=URL(raw);repeat(6){require(url.protocol=="https"&&url.userInfo==null&&url.ref==null&&url.host in DOWNLOAD_HOSTS){"Update URL is outside the official publisher"};val c=url.openConnection() as HttpsURLConnection;c.instanceFollowRedirects=false;c.connectTimeout=15000;c.readTimeout=30000;c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("User-Agent","VaultorAndroid");val status=c.responseCode;if(status in listOf(301,302,303,307,308)){val target=c.getHeaderField("Location")?:error("Missing update redirect");url=URL(url,target);c.disconnect()}else {require(status==200){"Publisher refused update request ($status); use manual download"};return c}};error("Too many publisher redirects")}
 private fun json(url:String,max:Int):String{metadataFetcher?.let {fetch->val raw=fetch(url);require(raw.toByteArray().size<=max);return raw};val c=connect(url);try{val bytes=c.inputStream.use {it.readNBytes(max+1)};require(bytes.size<=max){"Publisher metadata exceeds bounds"};return String(bytes,Charsets.UTF_8)}finally{c.disconnect()}}
 fun check(){action {phase("checking","Checking official Android prereleases");val releases=JSONArray(json("https://api.github.com/repos/$REPO/releases?per_page=100",2*1048576));require(releases.length()<=100){"Publisher release list exceeds100 entries"};var best:JSONObject?=null;for(n in 0 until releases.length()){check(!cancel){"Update check paused"};val r=releases.getJSONObject(n);if(r.optBoolean("draft")||!r.optString("tag_name").startsWith("android/v"))continue;val assets=r.optJSONArray("assets")?:continue;val meta=(0 until assets.length()).map {assets.getJSONObject(it)}.firstOrNull {it.optString("name")=="android-release.json"}?:continue;val m=JSONObject(json(meta.getString("browser_download_url"),16384));if(m.optString("applicationId")!=trust.getString("applicationId")||m.optBoolean("developmentDiagnostics")||m.optInt("apiProtocol")!=trust.getInt("apiProtocol")||m.optLong("versionCode")<=installed().longVersionCode||m.optInt("minimumApi")>android.os.Build.VERSION.SDK_INT)continue;val apk=(0 until assets.length()).map {assets.getJSONObject(it)}.firstOrNull {it.optString("name")==m.optString("apk")}?:continue;require(m.optString("sha256").matches(Regex("[a-f0-9]{64}"))&&m.optLong("size") in 1..MAX&&apk.getLong("size")==m.getLong("size"));if(best==null||m.getLong("versionCode")>best!!.getLong("versionCode"))best=JSONObject(m.toString()).put("url",apk.getString("browser_download_url"))};val row=read();if(best==null){row.remove("available");row.put("phase","current").put("detail","No newer compatible published Android build. Local acceptance candidates are not public updates.")}else row.put("available",best).put("phase","available").put("detail","New publisher candidate found. Download and verify before Android installation consent.");save(row)}}
 private fun hash(file:File):String{val d=MessageDigest.getInstance("SHA-256");file.inputStream().use {i->val b=ByteArray(65536);while(true){val n=i.read(b);if(n<0)break;d.update(b,0,n)}};return d.digest().joinToString(""){"%02x".format(it)}}
 internal fun verify(file:File,currentCode:Long=installed().longVersionCode):JSONObject {require(file.isFile&&file.length() in 1..MAX){"APK size is unsupported"};val result=ApkVerifier.Builder(file).setMinCheckedPlatformVersion(android.os.Build.VERSION.SDK_INT).setMaxCheckedPlatformVersion(android.os.Build.VERSION.SDK_INT).build().verify();require(result.isVerified){"APK cryptographic signature failed. Nothing will be installed."};val certificates=result.signerCertificates;require(certificates.size==1&&MessageDigest.getInstance("SHA-256").digest(certificates.single().encoded).joinToString(""){"%02x".format(it)}==trust.getString("signerSha256")){"APK signer differs from the original Vaultor identity"};val info=ctx.packageManager.getPackageArchiveInfo(file.path,PackageManager.PackageInfoFlags.of(PackageManager.GET_META_DATA.toLong()))?:error("APK cannot be parsed");require(info.packageName==trust.getString("applicationId")){"APK package differs"};require(info.longVersionCode>currentCode){"Downgrades and same-version updates are refused"};require((info.applicationInfo?.minSdkVersion?:Int.MAX_VALUE)<=android.os.Build.VERSION.SDK_INT){"APK requires a newer Android version"};require(info.applicationInfo?.flags?.and(android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE)==0){"Debug builds cannot be installed as updates"};require(info.applicationInfo?.metaData?.getBoolean("com.vaultor.DEVELOPMENT_DIAGNOSTICS",false)!=true){"Development diagnostic builds are not ordinary updates"};java.util.zip.ZipFile(file).use {zip->val entry=zip.getEntry("assets/release-trust.json")?:error("APK has no signed compatibility declaration");require(entry.size in 1..16384);val nativeAbis=zip.entries().asSequence().map {it.name}.filter {it.startsWith("lib/")&&it.endsWith(".so")}.map {it.split('/')[1]}.toSet();require(nativeAbis.isEmpty()||android.os.Build.SUPPORTED_ABIS.any {it in nativeAbis}){"APK does not support this device architecture"};val compatibility=JSONObject(zip.getInputStream(entry).bufferedReader().use {it.readText()});require(compatibility.getInt("apiProtocol")==trust.getInt("apiProtocol")){"Update requires a different host protocol. Review compatibility before manual installation."}};return JSONObject().put("versionName",info.versionName).put("versionCode",info.longVersionCode).put("sha256",hash(file)).put("bytes",file.length())}
 private fun stage(input:InputStream,expected:JSONObject?){val part=File(root,"candidate.part");val old=File(root,"candidate.apk");require(root.usableSpace>(expected?.optLong("size")?:MAX)+16*1048576){"Not enough update staging space (up to256MiB plus reserve). Existing app and queues are retained."};phase("downloading","Privately staging update; installation still requires consent");save(read().put("downloadedBytes",0).put("totalBytes",expected?.optLong("size")?:JSONObject.NULL));var count=0L;var reported=0L;FileOutputStream(part).use {out->input.use {source->val buffer=ByteArray(65536);while(true){check(!cancel){"Download paused"};val n=source.read(buffer);if(n<0)break;count+=n;require(count<=MAX&&(expected==null||count<=expected.getLong("size"))){"APK exceeds advertised size"};require(root.usableSpace>n+16L*1048576){"Update storage filled. Existing app and protected queues remain."};out.write(buffer,0,n);if(count-reported>=1048576){reported=count;save(read().put("downloadedBytes",count).put("totalBytes",expected?.optLong("size")?:JSONObject.NULL))}};out.fd.sync()}};phase("verifying","Verifying APK signature, original signer, package, version and compatibility");val verified=verify(part);if(expected!=null)require(verified.getString("sha256")==expected.getString("sha256")&&verified.getLong("bytes")==expected.getLong("size")&&verified.getLong("versionCode")==expected.getLong("versionCode")&&verified.getString("versionName")==expected.getString("versionName")){"APK differs from publisher metadata"};check(!cancel);check(part.renameTo(old)){"Could not finalize verified update"};save(read().put("candidate",verified).put("phase","ready").put("detail","Original-signer APK verified. Install opens Android consent; app data is retained."))}
 fun download(){action {val expected=read().getJSONObject("available");val c=connect(expected.getString("url"));try{stage(c.inputStream,expected)}finally{c.disconnect()}}}
 fun acquire(uri:Uri){require(uri.scheme=="content");action{val stream=ctx.contentResolver.openInputStream(uri)?:error("Provider cannot read APK");stage(stream,null)}}
 fun pause(){cancel=true}
 fun install(){action{val file=File(root,"candidate.apk");val verified=verify(file);require(verified.getString("sha256")==read().getJSONObject("candidate").getString("sha256")){"Staged update changed"};val folder=File(ctx.cacheDir,"media-share").apply {mkdirs()};val shared=File(folder,"vaultor-update.apk");require(folder.usableSpace>file.length()+16L*1048576);file.copyTo(shared,true);require(hash(shared)==verified.getString("sha256"));android.os.Handler(ctx.mainLooper).post {try{val activity=activityProvider?.invoke()?:error("Open Vaultor first");if(!ctx.packageManager.canRequestPackageInstalls()){phase("permission","Allow installs from Vaultor in Android Settings, return, then press Install again.");activity.startActivity(Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+ctx.packageName)))}else {val uri=FileProvider.getUriForFile(ctx,ctx.packageName+".media",shared);activity.startActivity(Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").apply {clipData=ClipData.newRawUri("Verified update",uri)}.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));phase("consent","Android installer opened. Installation success is confirmed only after the new app starts.")}}catch(_:Exception){phase("error","Android installer unavailable or declined. Verified APK and current app data remain.")}}}}
 fun picker(){val activity=activityProvider?.invoke()?:error("Open Vaultor first");activity.startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/vnd.android.package-archive"),7410)}
 fun openReleases(){ctx.startActivity(Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/$REPO/releases")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}
}
